/* Hard landscape lock: dismissed only hides overlay in landscape */
@media (orientation: landscape) {
  #portraitOverlay.dismissed { display: none !important; }
}
@media (orientation: portrait) and (hover: none) and (pointer: coarse) {
  #portraitOverlay.dismissed { display: flex !important; }
}

function resizeCanvas() {
  const container = document.getElementById('gameContainer');
  W = container.clientWidth;
  H = container.clientHeight;
  canvas.width = W;
  canvas.height = H;
  FLOOR_Y = H - 80;
}

function resizeCanvas() {
  const container = document.getElementById('gameContainer');
  const prevFloor = FLOOR_Y;
  const prevH = H;
  // Prefer laid-out stage; fall back to fullscreen element / visualViewport (FS settle)
  let cw = container ? container.clientWidth : 0;
  let ch = container ? container.clientHeight : 0;
  try {
    const fs = (typeof fullscreenElement === 'function') ? fullscreenElement() : null;
    const vv = window.visualViewport;
    if (fs && (!cw || !ch)) {
      if (fs === container) {
        cw = cw || Math.round(fs.clientWidth * 0.99) || fs.clientWidth;
        ch = ch || Math.round(cw * 9 / 16);
      } else {
        cw = cw || fs.clientWidth;
        ch = ch || fs.clientHeight;
      }
    }
    if (vv && (!cw || !ch)) {
      cw = cw || Math.round(vv.width);
      ch = ch || Math.round(vv.height);
    }
  } catch (e) {}
  W = Math.max(1, cw || window.innerWidth || 1);
  H = Math.max(1, ch || window.innerHeight || 1);
  canvas.width = W;
  canvas.height = H;
  // Keep a playable floor band; raise ground line ~10px vs prior (H-80 / adaptive)
  FLOOR_Y = H - Math.max(56, Math.min(96, Math.round(H * 0.11))) - 10;
  if (prevH > 0 && typeof PLAYER !== 'undefined') {
    const dy = FLOOR_Y - prevFloor;
    PLAYER.y += dy;
    if (PLAYER.onGround) PLAYER.y = FLOOR_Y - (PLAYER.ducking ? PLAYER.h * 0.5 : PLAYER.h);
    PLAYER.defaultX = W * 0.18;
    PLAYER.x = Math.max(8, Math.min(PLAYER.x, W - PLAYER.w - 8));
  }
}

function onViewportChange() {
  const container = document.getElementById('gameContainer');
  if (container) void container.offsetWidth; // force reflow (screenshot/resize clue)
  resizeCanvas();
  if (gameState === 'game') initBgLayers();
}
function settleFullscreenLayout() {
  /* Multiple passes: rAF, rAF+rAF, delayed timeouts — layout often lags FS chrome */
  const delays = [50, 100, 180, 280, 350];
  const pass = function () { onViewportChange(); };
  pass();
  requestAnimationFrame(function () {
    pass();
    requestAnimationFrame(function () {
      pass();
      delays.forEach(function (ms) { setTimeout(pass, ms); });
    });
  });
}
window.addEventListener('resize', onViewportChange);
if (window.visualViewport) {
  window.visualViewport.addEventListener('resize', onViewportChange);
  window.visualViewport.addEventListener('scroll', onViewportChange);
}

window.addEventListener('orientationchange', () => {
  setTimeout(() => { // small delay for orientation to settle
    if (window.innerWidth > window.innerHeight) {
      document.getElementById('portraitOverlay').classList.add('dismissed');
    }
  }, 300);
});

function isPortraitTouch() {
  try {
    if (window.matchMedia && window.matchMedia('(orientation: portrait) and (hover: none) and (pointer: coarse)').matches) return true;
  } catch (e) {}
  const touch = ('ontouchstart' in window) || (navigator.maxTouchPoints > 0);
  return !!(touch && window.innerHeight > window.innerWidth);
}
function applyPortraitLock() {
  const ov = document.getElementById('portraitOverlay');
  if (!ov) return;
  if (isPortraitTouch()) {
    ov.classList.remove('dismissed');
    window.__hocPortraitLocked = true;
    try {
      if (typeof PLAYER !== 'undefined') { PLAYER.hdir = 0; PLAYER.jumpHeld = false; PLAYER.ducking = false; }
    } catch (e) {}
  } else {
    const was = !!window.__hocPortraitLocked;
    ov.classList.add('dismissed');
    window.__hocPortraitLocked = false;
    if (was || gameState === 'game') settleFullscreenLayout();
    else onViewportChange();
  }
}
window.addEventListener('orientationchange', () => {
  setTimeout(() => { // small delay for orientation to settle
    applyPortraitLock();
    settleFullscreenLayout();
  }, 300);
});
if (window.matchMedia) {
  try {
    const mq = window.matchMedia('(orientation: portrait)');
    const onMq = function () { applyPortraitLock(); settleFullscreenLayout(); };
    if (mq.addEventListener) mq.addEventListener('change', onMq);
    else if (mq.addListener) mq.addListener(onMq);
  } catch (e) {}
}
